def discounted(price, quantity):
    if quantity >= 10:
        return price * quantity * 0.9
    return price * quantity

from pricing import discounted as price_line

def total_order(items):
    total = 0
    for price, quantity in items:
        if quantity <= 0:
            continue
        total = total + price_line(price, quantity)
    return total
